import org.junit.jupiter.api.Assertions;
import org.opentest4j.AssertionFailedError;

public class FoundationObservation {
    private static int divideByZero() {
        int divisor = 0;
        return 5 / divisor;
    }

    public static void main(String[] args) {
        int expected = 5;
        int changed = 999;
        int zero = 0;
        Assertions.assertNotNull(expected);
        System.out.println("weak_5:PASS");
        Assertions.assertNotNull(changed);
        System.out.println("weak_999:PASS");
        Assertions.assertNotNull(zero);
        System.out.println("weak_0:PASS");
        Assertions.assertEquals(5, expected);
        System.out.println("exact_5:PASS");
        try {
            Assertions.assertEquals(5, changed);
            throw new IllegalStateException("Expected assertion failure");
        } catch (AssertionFailedError e) {
            System.out.println("exact_999:EXPECTED_ASSERTION_FAILURE");
        }
        try {
            Assertions.assertNotNull((Object) null);
            throw new IllegalStateException("Expected null assertion failure");
        } catch (AssertionFailedError e) {
            System.out.println("weak_null:EXPECTED_ASSERTION_FAILURE");
        }
        try {
            Assertions.assertNotNull(divideByZero());
            throw new IllegalStateException("Expected arithmetic exception before assertion");
        } catch (ArithmeticException e) {
            System.out.println("divide_zero_before_assertion:EXPECTED_ARITHMETIC_EXCEPTION");
        }
    }
}
